-- ========================================
-- MÓDULO "SKILL MATRIX" — script para correr en el
-- SQL Editor del proyecto Supabase de Planificación y Avance
-- (el mismo que usa "colaboradores" y "reconocimientos": iaitqquphjohgsmelhcj).
-- ========================================
-- Este proyecto no tiene migraciones ni ORM: cada tabla se crea a
-- mano en el dashboard de Supabase. Corre este script una sola vez
-- (crea las 3 tablas y carga de una vez los datos reales de
-- "Skill Matrix LATAM_Alicorp_2026_Q2.xlsx" — 103 colaboradores,
-- 80 habilidades, ~8240 niveles).

-- ========================================
-- TABLAS
-- ========================================

create table if not exists public.skill_matrix_colaboradores (

    dni text primary key,
    nombre_completo text not null,
    turno text,
    cargo text,
    activo boolean not null default true,
    updated_at timestamptz not null default now()

);

create table if not exists public.skill_matrix_habilidades (

    -- 'LAT-001'..etc para las habilidades que traían código en el Excel;
    -- 'GEN-01'..'GEN-10' generado acá para las 10 habilidades de
    -- inducción/generales que en el Excel no tenían código propio.
    codigo text primary key,
    categoria text not null,   -- GENERAL / INBOUND / OUTBOUND / FACTURACION / LIQUIDACION / GESTION DE MERMAS / INVENTARIO
    nombre text not null,
    orden int not null

);

create table if not exists public.skill_matrix_niveles (

    id bigint generated by default as identity primary key,

    -- Sin FK "on delete cascade" duro hacia un roster que se reemplaza
    -- solo (como colaboradores_activos) — acá dni/codigo_habilidad SÍ
    -- referencian tablas propias de este módulo, que no se vacían solas,
    -- así que la cascada es segura (si se borra un colaborador o una
    -- habilidad de este módulo, sus niveles se van con él/ella).
    dni text not null references public.skill_matrix_colaboradores(dni) on delete cascade,
    codigo_habilidad text not null references public.skill_matrix_habilidades(codigo) on delete cascade,

    -- Escala validada contra el color condicional + fórmulas resumen
    -- del Excel original:
    --   0 = Sin evaluar   1 = Necesita entrenamiento (rojo)
    --   2 = Entrenado (verde)   3 = Multiplicador (negro)
    --   4 = No aplica a su puesto (gris)
    nivel smallint not null default 0 check (nivel between 0 and 4),

    actualizado_en timestamptz not null default now(),
    actualizado_por text,

    unique (dni, codigo_habilidad)

);

-- ========================================
-- RLS — mismas políticas permisivas que el resto del proyecto
-- (reconocimientos, colaboradores_activos, etc.): se leen/escriben
-- desde el navegador con la publishable key (anon), sin backend
-- propio. El control real de quién puede editar vive en el front
-- (shared/auth.js + sesion.rol === "Administrador"), no acá.
-- ========================================

alter table public.skill_matrix_colaboradores enable row level security;
alter table public.skill_matrix_habilidades enable row level security;
alter table public.skill_matrix_niveles enable row level security;

drop policy if exists "skill_matrix_colaboradores_select_anon" on public.skill_matrix_colaboradores;
drop policy if exists "skill_matrix_colaboradores_insert_anon" on public.skill_matrix_colaboradores;
drop policy if exists "skill_matrix_colaboradores_update_anon" on public.skill_matrix_colaboradores;
drop policy if exists "skill_matrix_colaboradores_delete_anon" on public.skill_matrix_colaboradores;

create policy "skill_matrix_colaboradores_select_anon" on public.skill_matrix_colaboradores for select to anon using (true);
create policy "skill_matrix_colaboradores_insert_anon" on public.skill_matrix_colaboradores for insert to anon with check (true);
create policy "skill_matrix_colaboradores_update_anon" on public.skill_matrix_colaboradores for update to anon using (true) with check (true);
create policy "skill_matrix_colaboradores_delete_anon" on public.skill_matrix_colaboradores for delete to anon using (true);

drop policy if exists "skill_matrix_habilidades_select_anon" on public.skill_matrix_habilidades;
drop policy if exists "skill_matrix_habilidades_insert_anon" on public.skill_matrix_habilidades;
drop policy if exists "skill_matrix_habilidades_update_anon" on public.skill_matrix_habilidades;
drop policy if exists "skill_matrix_habilidades_delete_anon" on public.skill_matrix_habilidades;

create policy "skill_matrix_habilidades_select_anon" on public.skill_matrix_habilidades for select to anon using (true);
create policy "skill_matrix_habilidades_insert_anon" on public.skill_matrix_habilidades for insert to anon with check (true);
create policy "skill_matrix_habilidades_update_anon" on public.skill_matrix_habilidades for update to anon using (true) with check (true);
create policy "skill_matrix_habilidades_delete_anon" on public.skill_matrix_habilidades for delete to anon using (true);

drop policy if exists "skill_matrix_niveles_select_anon" on public.skill_matrix_niveles;
drop policy if exists "skill_matrix_niveles_insert_anon" on public.skill_matrix_niveles;
drop policy if exists "skill_matrix_niveles_update_anon" on public.skill_matrix_niveles;
drop policy if exists "skill_matrix_niveles_delete_anon" on public.skill_matrix_niveles;

create policy "skill_matrix_niveles_select_anon" on public.skill_matrix_niveles for select to anon using (true);
create policy "skill_matrix_niveles_insert_anon" on public.skill_matrix_niveles for insert to anon with check (true);
create policy "skill_matrix_niveles_update_anon" on public.skill_matrix_niveles for update to anon using (true) with check (true);
create policy "skill_matrix_niveles_delete_anon" on public.skill_matrix_niveles for delete to anon using (true);

create index if not exists idx_skill_matrix_habilidades_categoria on public.skill_matrix_habilidades (categoria);
create index if not exists idx_skill_matrix_niveles_dni on public.skill_matrix_niveles (dni);
create index if not exists idx_skill_matrix_niveles_codigo on public.skill_matrix_niveles (codigo_habilidad);

